import{_ as n,C as o,o as a,c as i,ag as t,E as s}from"./chunks/framework.CtWPcAmt.js";const A=JSON.parse('{"title":"Return Merchandise Authorization (RMA)","description":"","frontmatter":{},"headers":[],"relativePath":"orders/return-merchandise-authorization.md","filePath":"orders/return-merchandise-authorization.md","lastUpdated":1786111645000}'),l={name:"orders/return-merchandise-authorization.md"};function h(u,e,d,g,c,m){const r=o("ImagePopup");return a(),i("div",null,[e[0]||(e[0]=t('<h1 id="return-merchandise-authorization-rma" tabindex="-1">Return Merchandise Authorization (RMA) <a class="header-anchor" href="#return-merchandise-authorization-rma" aria-label="Permalink to &quot;Return Merchandise Authorization (RMA)&quot;">​</a></h1><p>RMA is the marketplace&#39;s returns workflow. When a customer wants to return or exchange an item they bought from a seller, they raise an RMA request from their storefront order, and the seller handles it from <strong>Sales → RMA</strong> — reviewing it, messaging the customer, moving it through its statuses, and refunding when the goods come back.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How returns reach the seller</li><li>The RMA statuses and how a request moves through them</li><li>How a seller messages, refunds, and reopens a return</li></ul></div><h2 id="how-returns-reach-the-seller" tabindex="-1">How returns reach the seller <a class="header-anchor" href="#how-returns-reach-the-seller" aria-label="Permalink to &quot;How returns reach the seller&quot;">​</a></h2><p>Returns start on the <strong>customer&#39;s</strong> side: from their order, a customer raises an RMA against specific items. The marketplace routes each request to the seller who sold those items, so it lands in that seller&#39;s RMA list. Whether a product can be returned at all — and under which rule — is set by the seller on the product&#39;s <strong>RMA</strong> tab (see <a href="/catalog/product-management#the-product-form">Product Management</a>).</p><h2 id="the-rma-requests-list" tabindex="-1">The RMA requests list <a class="header-anchor" href="#the-rma-requests-list" aria-label="Permalink to &quot;The RMA requests list&quot;">​</a></h2><p>Open <strong>Sales → RMA</strong> in the Seller Panel. Each request shows its <strong>RMA ID</strong>, the <strong>order ID</strong>, the <strong>customer name</strong>, the <strong>RMA status</strong>, whether it was a <strong>guest</strong> order, the <strong>order status</strong>, and the <strong>date</strong>.</p>',7)),s(r,{src:"/images/return-merchandise-authorization/rma-list.png",alt:"Seller RMA requests list"}),e[1]||(e[1]=t('<h2 id="working-a-return" tabindex="-1">Working a return <a class="header-anchor" href="#working-a-return" aria-label="Permalink to &quot;Working a return&quot;">​</a></h2><p>Open a request with its <strong>View</strong> action. The page gathers everything about the return: a <strong>General</strong> panel (date, package condition, notes, images), an <strong>Items</strong> panel (each returned item with its price, RMA quantity, resolution type, and reason), a <strong>Conversation</strong> thread, and <strong>Order / Customer</strong> details. The <strong>Status</strong> panel shows the current <strong>RMA Status</strong> and <strong>Order Status</strong>, and an <strong>Update Status</strong> control moves the request forward.</p>',2)),s(r,{src:"/images/return-merchandise-authorization/rma-status.png",alt:"Seller RMA request detail — status panel, update-status control, items, and conversation"}),e[2]||(e[2]=t('<ul><li><strong>Message the customer</strong> — the conversation thread lets the seller and customer exchange details (reasons, photos, resolution) with file attachments, right on the request.</li><li><strong>Update the status</strong> — move the request through its lifecycle. RMA statuses are <strong>Pending Review → Approved → Awaiting Return → Return In Transit → Refunded → Solved</strong>, with <strong>Request Declined</strong>, <strong>Item Canceled</strong>, and <strong>Request Canceled</strong> as end states. A brand-new request starts at <strong>Pending Review</strong>, from which you either <strong>Approve</strong> it or decline it (<strong>Request Declined</strong>); which statuses you can move to next depends on whether the resolution is a <strong>return</strong> or a <strong>cancellation</strong>.</li><li><strong>Refund on receipt</strong> — moving a return to <strong>Refunded</strong> processes the <strong>refund</strong> for the returned items (you can also refund the shipping). A refund needs the item to have been invoiced first.</li><li><strong>Reopen</strong> — if a request was declined and the admin allows it, the <strong>seller</strong> can <strong>reopen</strong> it, which returns it to <strong>Pending Review</strong>.</li></ul><div class="info custom-block"><p class="custom-block-title">Admin oversight</p><p>Admins see every seller&#39;s RMAs across the marketplace under <strong>Marketplace → Sales → RMA</strong>, and RMA availability and policy are governed by the admin. Each status change notifies the customer.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Respond to return messages quickly and keep the status current — a smooth returns experience protects your ratings and your <a href="/sellers/seller-account-health">account health</a>.</p></div>',3))])}const R=n(l,[["render",h]]);export{A as __pageData,R as default};
